(function(){"use strict";document.addEventListener("DOMContentLoaded",function(){var t=docsState.get(),o=document.getElementById("docs-sidebar");document.querySelectorAll("input[name=theme]").forEach(function(e){e.checked=e.value===t.theme,e.addEventListener("change",function(){docsState.set({theme:e.value})})}),document.querySelectorAll("input[name=color-mode]").forEach(function(e){e.checked=e.value===t.mode,e.addEventListener("change",function(){docsState.set({mode:e.value})})}),document.querySelectorAll("iframe.docs-demo").forEach(function(e){e.addEventListener("load",docsState.broadcast)}),docsState.broadcast(),o.addEventListener("click",function(e){var n=e.target.closest("a.nav-link")&&bootstrap.Offcanvas.getInstance(o);n&&n.hide()}),document.addEventListener("activate.bs.scrollspy",function(e){e.relatedTarget&&e.relatedTarget.scrollIntoView({block:"nearest"})}),document.querySelectorAll('[data-bs-toggle="tooltip"]').forEach(function(e){new bootstrap.Tooltip(e)}),document.querySelectorAll('[data-bs-toggle="popover"]').forEach(function(e){new bootstrap.Popover(e)})})})();
